 * KnockoutJS Template Binding Error Debugger
 * 
 * Helps debug binding errors by providing:
 * - The name of the property that failed to bind
 * - A list of available properties on the current binding context
 * - A suggestion for the closest matching property name (to catch typos)
 */

/**
 * Calculate the Levenshtein distance between two strings.
 * 
 * @param {string} s1 - First string
 * @param {string} s2 - Second string
 * @returns {number} The edit distance between the two strings
 */
function levenshteinDistance(s1, s2) {
  const m = s1.length;
  const n = s2.length;

  // Create a matrix to store distances
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Initialize base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = s1[i - 1] === s2[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,       // deletion
        dp[i][j - 1] + 1,       // insertion
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Create a debug helper for a KnockoutJS ViewModel.
 * 
 * @param {Object} viewModel - A plain JavaScript object with properties
 * @returns {Object} A debug helper object with diagnose method
 */
function createDebugHelper(viewModel) {
  // Get all own property names from the viewModel, sorted alphabetically
  const availableProperties = Object.getOwnPropertyNames(viewModel).sort();

  /**
   * Diagnose a missing property in binding context.
   * 
   * @param {string} propertyName - The name of the property that failed to bind
   * @returns {Object} Diagnostic result with missingProperty, availableProperties, and suggestion
   */
  function diagnoseMissingProperty(propertyName) {
    const suggestion = findClosestMatch(propertyName, availableProperties);

    return {
      error: true,
      missingProperty: propertyName,
      availableProperties: availableProperties,
      suggestion: suggestion
    };
  }

  return {
    diagnose: diagnoseMissingProperty,
    availableProperties: availableProperties
  };
}

/**
 * Find the closest matching property name from the available properties.
 * Only returns a suggestion if the Levenshtein distance is 3 or less.
 * If multiple properties tie, returns the one that comes first alphabetically.
 * 
 * @param {string} missingProperty - The property name that was not found
 * @param {string[]} availableProperties - Sorted array of available property names
 * @returns {string|null} The closest matching property name or null
 */
function findClosestMatch(missingProperty, availableProperties) {
  let closestMatch = null;
  let minDistance = Infinity;

  for (const prop of availableProperties) {
    const distance = levenshteinDistance(missingProperty, prop);

    if (distance > 3) {
      continue; // Only consider matches within distance 3
    }

    if (distance < minDistance) {
      minDistance = distance;
      closestMatch = prop;
    } else if (distance === minDistance) {
      // Tie-breaker: alphabetically first
      if (prop < closestMatch) {
        closestMatch = prop;
      }
    }
  }

  return minDistance <= 3 ? closestMatch : null;
}

module.exports = {
  createDebugHelper,
  diagnoseMissingProperty: function(propertyName, viewModel) {
    // For standalone use: create helper from viewModel and diagnose
    const helper = createDebugHelper(viewModel);
    return helper.diagnose(propertyName);
  },
  levenshteinDistance
};"}

