/**
 * Test script for KnockoutJS Template Binding Error Debugger
 */

const { createDebugHelper, levenshteinDistance } = require('./ko-debug.js');

// Sample ViewModel with properties
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create a debug helper instance
const helper = createDebugHelper(sampleViewModel);

// Test counter
let passed = 0;
let failed = 0;

function test(description, actual, expected) {
  const pass = JSON.stringify(actual) === JSON.stringify(expected);
  if (pass) {
    console.log(`PASS: ${description}`);
    passed++;
  } else {
    console.log(`FAIL: ${description}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
    failed++;
  }
}

console.log('=== KnockoutJS Template Binding Error Debugger Tests ===\n');

// ========== TEST 1: Diagnose missing property "item" (should suggest "items") ==========
{
  const result = helper.diagnose('item');
  test(
    'Test 1: Diagnose "item" should suggest "items"',
    result,
    {
      error: true,
      missingProperty: 'item',
      availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
      suggestion: 'items'
    }
  );
}

// ========== TEST 2: Diagnose missing property "selctedItem" (should suggest "selectedItem") ==========
{
  const result = helper.diagnose('selctedItem');
  test(
    'Test 2: Diagnose "selctedItem" should suggest "selectedItem"',
    result,
    {
      error: true,
      missingProperty: 'selctedItem',
      availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
      suggestion: 'selectedItem'
    }
  );
}

// ========== TEST 3: Diagnose missing property "completelyWrong" (should have null suggestion) ==========
{
  const result = helper.diagnose('completelyWrong');
  test(
    'Test 3: Diagnose "completelyWrong" should have null suggestion',
    result,
    {
      error: true,
      missingProperty: 'completelyWrong',
      availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
      suggestion: null
    }
  );
}

// ========== TEST 4: Diagnose missing property "isLoad" (should suggest "isLoading") ==========
{
  const result = helper.diagnose('isLoad');
  test(
    'Test 4: Diagnose "isLoad" should suggest "isLoading"',
    result,
    {
      error: true,
      missingProperty: 'isLoad',
      availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
      suggestion: 'isLoading'
    }
  );
}

// ========== TEST 5: Verify Levenshtein distance function ==========
{
  const d1 = levenshteinDistance('item', 'items');
  test(
    'Test 5: Levenshtein distance("item", "items") should be 1',
    d1,
    1
  );

  const d2 = levenshteinDistance('completelyWrong', 'items');
  test(
    'Test 6: Levenshtein distance("completelyWrong", "items") should be > 3',
    d2 > 3,
    true
  );

  const d3 = levenshteinDistance('selctedItem', 'selectedItem');
  test(
    'Test 7: Levenshtein distance("selctedItem", "selectedItem") should be 1',
    d3,
    1
  );

  const d4 = levenshteinDistance('isLoad', 'isLoading');
  test(
    'Test 8: Levenshtein distance("isLoad", "isLoading") should be 2',
    d4,
    2
  );
}

// ========== Summary ==========
console.log(`\n=== Test Summary: ${passed} passed, ${failed} failed ===`);

if (failed > 0) {
  process.exit(1);
} else {
  process.exit(0);
}
